// Generate deterministic event_id from timestamp and workflow name
const eventId = `gdacs-ingestion-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
const workflowName = 'Harvy — gdacs Ingestion';
const timestamp = new Date().toISOString();

return {
  eventId,
  workflowName,
  timestamp,
  source: 'gdacs',
  version: '1.0.0'
};

// Set up Webshare proxy configuration
const proxyConfig = {
  proxyType: 'http',
  proxyHost: process.env.WEBSHARE_PROXY_URL.split('://')[1].split(':')[0],
  proxyPort: parseInt(process.env.WEBSHARE_PROXY_URL.split(':')[2]),
  proxyUsername: process.env.WEBSHARE_PROXY_USER || '',
  proxyPassword: process.env.WEBSHARE_PROXY_PASS || ''
};

// GDACS API configuration
const gdacsConfig = {
  baseUrl: 'https://www.gdacs.org/',
  endpoints: {
    alerts: 'api/v2/alerts',
    events: 'api/v2/events',
    rss: 'rss.xml'
  },
  defaultParams: {
    format: 'json',
    limit: 1000
  }
};

return { proxyConfig, gdacsConfig };

// Process GDACS alerts with provenance and deduplication
const alerts = items.map(item => {
  const alert = item.json;

  // Generate deterministic event_id for each alert
  const alertEventId = `gdacs-alert-${alert.id}-${alert.timestamp}`;

  // Extract provenance information
  const provenance = {
    source: 'gdacs.org',
    sourceUrl: alert.link || alert.url,
    retrievedAt: new Date().toISOString(),
    license: 'CC-BY-4.0',
    attribution: 'Global Disaster Alert and Coordination System (GDACS)',
    dataQuality: 'machine-readable-api'
  };

  // Add metadata
  return {
    ...alert,
    eventId: alertEventId,
    workflowName: 'Harvy — gdacs Ingestion',
    ingestionTimestamp: new Date().toISOString(),
    provenance,
    _harvy_metadata: {
      source: 'gdacs',
      type: 'alert',
      version: '2.0'
    },
    // Deduplication fields
    dedupeKey: `${alert.id}-${alert.timestamp}`,
    // Backfill tracking
    backfillCursor: item.json.backfillCursor || $node["Get Backfill Cursor"].json["backfillCursor"]
  };
});

return alerts;

// Deduplication check using data table
const { $checkDedupe } = require('n8n-workflow');

const alerts = items;
const uniqueAlerts = [];
const dedupeKeys = new Set();

for (const alert of alerts) {
  const dedupeKey = alert.dedupeKey;
  const exists = await $checkDedupe('gdacs_dedupe_table', dedupeKey);

  if (!exists) {
    uniqueAlerts.push(alert);
    dedupeKeys.add(dedupeKey);
  } else {
    // Log duplicate
    $node["Log Duplicates"].addItem({
      json: {
        eventId: alert.eventId,
        alertId: alert.id,
        timestamp: alert.timestamp,
        message: 'Duplicate alert detected and skipped',
        dedupeKey: dedupeKey,
        ingestionTimestamp: new Date().toISOString()
      }
    });
  }
}

// Store dedupe keys for batch insertion
return { uniqueAlerts, dedupeKeys };

// Log duplicates to harvy_errors table
const duplicates = items.filter(item => item.json.message === 'Duplicate alert detected and skipped');

if (duplicates.length > 0) {
  console.warn(`Found ${duplicates.length} duplicate alerts`);

  // Log to OpenObserve
  $node["OpenObserve Logger"].addItem({
    json: {
      level: 'warning',
      message: 'GDACS duplicate alerts detected',
      count: duplicates.length,
      workflow: 'Harvy — gdacs Ingestion',
      timestamp: new Date().toISOString()
    }
  });
}

return items;

// Prepare data for R2 and PostgreSQL
const alerts = items.map(item => item.json);

// Split into raw and processed
const rawData = alerts.map(alert => ({
  eventId: alert.eventId,
  source: 'gdacs',
  rawJson: JSON.stringify(alert),
  timestamp: alert.timestamp,
  ingestionTimestamp: alert.ingestionTimestamp,
  provenance: JSON.stringify(alert.provenance)
}));

const processedData = alerts.map(alert => ({
  eventId: alert.eventId,
  alertId: alert.id,
  eventType: alert.eventType || 'unknown',
  severity: alert.severity || 'unknown',
  title: alert.title || '',
  description: alert.description || '',
  timestamp: alert.timestamp,
  location: alert.location ? JSON.stringify(alert.location) : '{}',
  affectedPopulation: alert.affectedPopulation || 0,
  evacuation: alert.evacuation || 0,
  workflowName: alert.workflowName,
  ingestionTimestamp: alert.ingestionTimestamp,
  backfillCursor: alert.backfillCursor || $node["Get Backfill Cursor"].json["backfillCursor"]
}));

return { rawData, processedData };

// Write raw data to R2 (harvy-raw bucket)
const { $writeR2 } = require('n8n-workflow');
const rawData = items[0].json.rawData;

for (const record of rawData) {
  await $writeR2('harvy-raw', `gdacs/${record.timestamp.split('T')[0]}/${record.eventId}.json`, record.rawJson, {
    contentType: 'application/json',
    metadata: {
      source: 'gdacs',
      workflow: 'Harvy — gdacs Ingestion',
      eventId: record.eventId
    }
  });
}

return items;

// Write processed data to PostgreSQL
const { $writePostgres } = require('n8n-workflow');
const processedData = items[0].json.processedData;

for (const record of processedData) {
  await $writePostgres('gdacs_alerts', record);
}

return items;

// Log success to OpenObserve
const count = items.length;
const workflowName = 'Harvy — gdacs Ingestion';
const timestamp = new Date().toISOString();

console.log(`Successfully processed ${count} GDACS alerts`);

$node["OpenObserve Logger"].addItem({
  json: {
    level: 'info',
    message: 'GDACS ingestion completed successfully',
    count: count,
    workflow: workflowName,
    timestamp: timestamp,
    eventId: $node["Generate Metadata"].json["eventId"]
  }
});

return items;

// Log errors to harvy_errors table
const errors = [];
if (items.length === 0) {
  errors.push({
    eventId: $node["Generate Metadata"].json["eventId"],
    workflow: 'Harvy — gdacs Ingestion',
    errorType: 'empty_result',
    message: 'No alerts returned from GDACS API',
    timestamp: new Date().toISOString(),
    severity: 'warning'
  });
}

if (errors.length > 0) {
  console.error('GDACS ingestion encountered errors:', errors);

  for (const error of errors) {
    $node["OpenObserve Logger"].addItem({
      json: {
        level: error.severity,
        message: error.message,
        workflow: error.workflow,
        timestamp: error.timestamp,
        errorType: error.errorType
      }
    });
  }
}

return items;

// OpenObserve logging node
// This is a no-op in the workflow JSON as OpenObserve is configured at instance level
return items;
